 * @brief aclnnFlashAttentionVarLenScoreEnhanceV5的第二段接口，用于执行计算。
 */
aclnnStatus aclnnFlashAttentionVarLenScoreEnhanceV5(
    void *workspace,
    uint64_t workspaceSize,
    aclOpExecutor *executor,
    const aclrtStream stream);

#ifdef __cplusplus
}
#endif

#endif // OP_API_INC_LEVEL2_ACLNN_FLASH_ATTENTION_SCORE_ENHANCE_H_

